import { revalidateTag } from 'next/cache';

export type Post = {
  id: string;
  title: string;
  content: string;
  createdAt: Date;
};

let posts: Post[] = [];

export function getPosts(): Post[] {
  return posts;
}

export async function createPost(title: string, content: string): Promise<Post> {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    content,
    createdAt: new Date(),
  };

  posts.push(post);

  revalidateTag('posts');

  return post;
}

